 Secondary\' as marketplace, sum(UNITS_SOLD) as quantity, sum(GMV) as Revenue from hox_db.maplemonk.HOX_SALES group by 1,2,3,4,5,6 ) as o left join skus a on lower(o.sku_number) = lower(a.marketplace_sku) left join product_names b on lower(coalesce(a.master_sku, o.sku_number)) = lower(b.component_sku) )as o left join product_base a on lower(o.sku) = lower(a.skucode) left join product_base_sheet c on lower(o.sku) = lower(c.SKU_CODE) )as o ;",
